pub fn get_current_mode(value: *mut open_platform_Data_Model::OperatingMode) -> bool
{
  unsafe {
    let guard = IN_current_mode.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

